import { cursor } from './cursor';
import { gamePaused } from './game';
import { gameStore } from './createGameStore';
import { derived } from 'svelte/store';

export const keyboardDisabled = derived(
	[cursor, gameStore, gamePaused],
	([$cursor, $gameStore, $gamePaused]) => {

		if ($gamePaused) return true;

		if ($cursor.x === null || $cursor.y === null) return true;

		const initial = $gameStore.game.getInitialSudoku().getGrid();
		const isGiven = initial[$cursor.y][$cursor.x] !== 0;

		return isGiven;
	}
);